class OrderSender extends AbstractPersistentActorWithAtLeastOnceDelivery {
  override def receiveCommand: Receive = {
    case PlaceOrder(o) =>
      persist(OrderPlaced(o.id)) { _ =>
        deliver(o.destination)(deliveryId => SendOrder(deliveryId, o))  // journaled
      }
    case Ack(orderId, deliveryId) =>
      persist(OrderAcked(orderId)) { _ => confirmDelivery(deliveryId) }
  }
  override def receiveRecover: Receive = { case _: OrderEvent => }
}

